type Call struct{ Op string; Amount int }

type fakeLedger struct {
	mu      sync.Mutex
	balance int
	calls   []Call
}

func (f *fakeLedger) Deposit(amount int) {
	f.mu.Lock(); defer f.mu.Unlock()
	f.balance += amount                                // working behaviour
	f.calls = append(f.calls, Call{"deposit", amount}) // recorded interaction
}
